package ru.truetv.launcher;

import android.content.*;
import android.database.*;
import android.database.sqlite.*;
import android.net.Uri;
import android.os.*;
import android.provider.DocumentsContract;
import java.io.*;
import java.util.*;

/** One persistent document identity table, shared by the native manager and its provider. */
public final class FileStore extends SQLiteOpenHelper {
 public static final String AUTHORITY="ru.truetv.launcher.documents";
 private static FileStore instance;private final Context context;
 public static synchronized FileStore get(Context c){if(instance==null)instance=new FileStore(c.getApplicationContext());return instance;}
 private FileStore(Context c){super(c,"file-documents.db",null,1);context=c;}
 public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE documents (id TEXT PRIMARY KEY, root TEXT NOT NULL, relative TEXT NOT NULL, UNIQUE(root,relative))");}
 public void onUpgrade(SQLiteDatabase db,int oldVersion,int newVersion){}
 public static final class Root {public final String id,title;public final File file;Root(String id,String title,File file){this.id=id;this.title=title;this.file=file;}}
 public static final class Node {public final String id,root;public final File file;Node(String id,String root,File file){this.id=id;this.root=root;this.file=file;}public boolean directory(){return file.isDirectory();}public boolean root(){return id.startsWith("root:");}}
 public List<Root> roots(){ArrayList<Root> result=new ArrayList<>();try{File primary=Environment.getExternalStorageDirectory().getCanonicalFile();result.add(new Root("primary",Ui.word(context,"Память устройства","Device storage"),primary));LinkedHashSet<File> candidates=new LinkedHashSet<>();File[] privateVolumes=context.getExternalFilesDirs(null);if(privateVolumes!=null)for(File f:privateVolumes)if(f!=null){String path=f.getCanonicalPath(),marker="/Android/data/"+context.getPackageName()+"/files";if(path.endsWith(marker))candidates.add(new File(path.substring(0,path.length()-marker.length())));}File[] mounted=new File("/storage").listFiles();if(mounted!=null)for(File f:mounted)if(!f.getName().equals("emulated")&&!f.getName().equals("self"))candidates.add(f.getCanonicalFile());for(File f:candidates)if(!f.equals(primary)&&f.isDirectory()&&f.canRead())result.add(new Root("usb-"+UUID.nameUUIDFromBytes(f.getAbsolutePath().getBytes("UTF-8")),Ui.word(context,"USB / ","USB / ")+f.getName(),f));}catch(IOException ignored){}return result;}
 private Root root(String id)throws FileNotFoundException {for(Root r:roots())if(r.id.equals(id))return r;throw new FileNotFoundException("Хранилище отключено");}
 private boolean excluded(String relative){return Build.VERSION.SDK_INT>=30&&(relative.equals("Android/data")||relative.startsWith("Android/data/")||relative.equals("Android/obb")||relative.startsWith("Android/obb/"));}
 public synchronized Node node(String id)throws IOException {if(id==null)throw new FileNotFoundException("Нет документа");if(id.startsWith("root:")){Root r=root(id.substring(5));return new Node(id,r.id,r.file);}try(Cursor c=getReadableDatabase().query("documents",new String[]{"root","relative"},"id=?",new String[]{id},null,null,null)){if(!c.moveToFirst())throw new FileNotFoundException("Документ не найден");String relative=c.getString(1);if(excluded(relative))throw new FileNotFoundException("Каталог закрыт Android");File file=FileCore.resolve(root(c.getString(0)).file,relative);if(!file.exists())throw new FileNotFoundException("Файл больше не существует");return new Node(id,c.getString(0),file);}}
 public synchronized Node identify(File file)throws IOException {FileCore.regular(file);for(Root r:roots())if(FileCore.inside(r.file,file)){File canonical=file.getCanonicalFile();if(canonical.equals(r.file))return new Node("root:"+r.id,r.id,canonical);String relative=canonical.getPath().substring(r.file.getPath().length()+1);if(excluded(relative))throw new IOException("Каталог закрыт Android");try(Cursor c=getReadableDatabase().query("documents",new String[]{"id"},"root=? AND relative=?",new String[]{r.id,relative},null,null,null)){if(c.moveToFirst())return new Node(c.getString(0),r.id,canonical);}String id=UUID.randomUUID().toString();ContentValues v=new ContentValues();v.put("id",id);v.put("root",r.id);v.put("relative",relative);getWritableDatabase().insertOrThrow("documents",null,v);return new Node(id,r.id,canonical);}throw new IOException("Файл вне доступного хранилища");}
 public List<Node> children(Node parent)throws IOException {if(!parent.directory())throw new IOException("Это не папка");File[] files=parent.file.listFiles();if(files==null)throw new IOException("Нет доступа к папке. Разрешите доступ к файлам.");ArrayList<Node> result=new ArrayList<>();for(File f:files){if(f.getName().startsWith(".truetv-part-")||f.getName().startsWith(".ToTV-")||f.getName().startsWith(".pending-"))continue;try{result.add(identify(f));}catch(IOException ignored){}}Collections.sort(result,(a,b)->{if(a.directory()!=b.directory())return a.directory()?-1:1;return a.file.getName().compareToIgnoreCase(b.file.getName());});return result;}
 public String title(Node n){if(n.root())try{return root(n.root).title;}catch(Exception ignored){}return n.file.getName();}
 public Node parent(Node n)throws IOException {return n.root()?n:identify(n.file.getParentFile());}
 public Uri uri(Node n){return DocumentsContract.buildDocumentUri(AUTHORITY,n.id);}
 public Node fromUri(Uri uri)throws IOException {if(uri==null||!AUTHORITY.equals(uri.getAuthority()))throw new IOException("Другой источник файлов");try{return node(DocumentsContract.getDocumentId(uri));}catch(IllegalArgumentException noDocument){return node(DocumentsContract.getTreeDocumentId(uri));}}
 public boolean treeAllowed(Node n){if(!n.directory())return false;return Build.VERSION.SDK_INT<30||!n.root()&&!n.file.equals(new File(Environment.getExternalStorageDirectory(),Environment.DIRECTORY_DOWNLOADS));}
 public synchronized void changed(File before,File after)throws IOException {Root target=null;for(Root r:roots())if(FileCore.inside(r.file,after)){target=r;break;}if(target==null)throw new IOException("Неизвестное хранилище");SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try(Cursor c=db.query("documents",new String[]{"id","root","relative"},null,null,null,null,null)){while(c.moveToNext()){Root old;try{old=root(c.getString(1));}catch(IOException gone){continue;}File f=new File(old.file,c.getString(2));String path=f.getAbsolutePath(),prefix=before.getAbsolutePath();if(path.equals(prefix)||path.startsWith(prefix+"/")){File dest=new File(after,path.substring(prefix.length()).replaceFirst("^/",""));ContentValues v=new ContentValues();v.put("root",target.id);v.put("relative",dest.getCanonicalPath().substring(target.file.getPath().length()+1));db.update("documents",v,"id=?",new String[]{c.getString(0)});}}db.setTransactionSuccessful();}finally{db.endTransaction();}notifyChange();}
 public void notifyChange(){context.getContentResolver().notifyChange(Uri.parse("content://"+AUTHORITY+"/document"),null);context.getContentResolver().notifyChange(DocumentsContract.buildRootsUri(AUTHORITY),null);}
 public Node create(Node parent,String name,boolean dir)throws IOException {Node made=identify(FileCore.create(parent.file,name,dir));notifyChange();return made;}
 public Node rename(Node n,String name)throws IOException {if(n.root())throw new IOException("Хранилище нельзя переименовать");File old=n.file,target=FileCore.rename(old,name);changed(old,target);return node(n.id);}
 public void delete(Node n)throws IOException {if(n.root())throw new IOException("Корень хранилища нельзя удалить");FileCore.erase(n.file,FileCore.NEVER);purgeMissing();notifyChange();}
 public synchronized void purgeMissing(){SQLiteDatabase db=getWritableDatabase();ArrayList<String> gone=new ArrayList<>();try(Cursor c=db.query("documents",new String[]{"id"},null,null,null,null,null)){while(c.moveToNext())try{node(c.getString(0));}catch(IOException e){gone.add(c.getString(0));}}for(String id:gone)db.delete("documents","id=?",new String[]{id});}
}
